$(function () {

    console.log('3')

    console.log('2')

    // GNB

    $("#gnb").sMenu({

        on_menu1: "3",

        on_menu2: "2",

        hover_class: "hover"

    });

    // SNB

    $("#snb").sMenu({

        on_menu1: "2",

        on_menu2: "1",

        hover_class: "hover",

        is_snb: true

    });

    $("#snb li").each(function () {
        const $li = $(this);
        const $icon = $li.find("a > i");

        if ($li.hasClass("child_1depth")) {
            $icon.attr("class", "xi-plus-min"); // 초기 상태는 접힘
        } else {
            $icon.attr("class", "xi-angle-right-min");
        }
    });

    // 아코디언 메뉴 페이지에서 아코디언 펼쳐지게 하기
    $('#snb li.depth-1.on > ul').show();

    // 아이콘도 바꿔주기
    $('#snb li.depth-1.on').each(function () {
        const $li = $(this);
        const $submenu = $li.children('ul');
        const $icon = $li.children('a').find('i');

        // 서브메뉴가 있는 경우만 펼치고 아이콘 변경
        if ($submenu.length > 0 && $icon.hasClass('xi-plus-min')) {
            $submenu.show();
            $icon.removeClass('xi-plus-min').addClass('xi-minus-min');
        }
    });

    // $(document).ready(function() {
    //     // 아코디언 기능 추가
    //     $("#snb li.child_1depth > a").on("click", function(e) {
    //         const $li = $(this).parent("li");
    //         const $submenu = $li.children("ul");
    //         const $icon = $(this).find("i");

    //         if ($submenu.length === 0) return; // 서브메뉴가 없으면 무시

    //         e.preventDefault(); // 링크 이동 방지

    //         // 아코디언 toggle
    //         if ($submenu.is(":visible")) {
    //             $submenu.slideUp(200);
    //             $icon.attr("class", "xi-plus-min");
    //         } else {
    //             $submenu.slideDown(200);
    //             $icon.attr("class", "xi-minus-min");
    //         }
    //     });
    // });

    $(document).ready(function () {
        // 아코디언 기능 추가 (한 개만 열리도록)
        $("#snb li.child_1depth > a").on("click", function (e) {
            const $li = $(this).parent("li");
            const $submenu = $li.children("ul");
            const $icon = $(this).find("i");

            if ($submenu.length === 0) return; // 서브메뉴가 없으면 무시

            e.preventDefault();               // 링크 이동 방지

            // 1) 현재 클릭한 메뉴가 닫혀 있는 상태라면,
            if (!$submenu.is(":visible")) {
                // └> 다른 열려 있는 메뉴들 모두 닫기
                $("#snb li.child_1depth").not($li).each(function () {
                    const $otherLi = $(this);
                    const $otherSubmenu = $otherLi.children("ul");
                    const $otherIcon = $otherLi.find("a > i");
                    if ($otherSubmenu.is(":visible")) {
                        $otherSubmenu.slideUp(200);
                        $otherIcon.attr("class", "xi-plus-min");
                    }
                });
                // └> 그리고 현재 메뉴 열기
                $submenu.slideDown(200);
                $icon.attr("class", "xi-minus-min");

                // 2) 이미 열려 있는 메뉴를 클릭한 경우 (토글)
            } else {
                $submenu.slideUp(200);
                $icon.attr("class", "xi-plus-min");
            }
        });
    });


    // lnb 마지막 메뉴 폰트색상 변경
    $('#lnb-inner ul li:last-child a').css({
        'color': 'rgba(0, 0, 0, 0.8)'
    });

    $('.gnbM depth-1 a i.xi-angle-right-min').css({
        'display': 'none'
    });


});

$(document).ready(function () {
    // url 복사
    $('.btn-copy-url').on('click', function (e) {
        e.preventDefault();

        const $url = $('<input>');
        $('body').append($url);
        $url.val(window.location.href).select();

        try {
            const success = document.execCommand('copy');
            if (success) {
                alert('현재 페이지 URL이 복사되었습니다!');
            } else {
                alert('복사에 실패했습니다. 수동으로 복사해주세요.');
            }
        } catch (err) {
            alert('이 브라우저에서는 복사 기능이 지원되지 않습니다.');
        }

        $url.remove();
    })


});

$(document).ready(function(){
    var hideOverlayTimer;

    function showOverlay() {
        clearTimeout(hideOverlayTimer);
        $('#gnb-overlay').show();
    }

    function hideOverlayWithDelay() {
        clearTimeout(hideOverlayTimer);
        hideOverlayTimer = setTimeout(function(){
            if ($('.menu-area-box:visible').length === 0) {
                $('#gnb-overlay').hide();
            }
        }, 0);
    }

    $('#gnb ul li.child_1depth').on('mouseenter', function(){
        showOverlay();
    }).on('mouseleave', function(){
        hideOverlayWithDelay();
    });

    $('.menu-area-box').on('mouseenter', function(){
        showOverlay();
    }).on('mouseleave', function(){
        hideOverlayWithDelay();
    });

    $('.header-logo, #gnb-btn').on('mouseenter', function(){
        hideOverlayWithDelay();
    });

    $('#gnb').on('mouseleave', function(){
        hideOverlayWithDelay();
    });

});

