$(document).ready(function(){
    // 버튼 클릭 시
    $('#gnb-btn > button').on('click', function(){
        var $menu = $('#gnb-btn .all-menu-back');
        var $icon = $('#gnb-icon');
        var $overlay = $('#gnb-btn .overlay');

        if ($menu.is(':visible')) {
            $menu.slideUp(250);
            $overlay.fadeOut(250);
            $icon.attr('src', 'https://wfps.or.kr/layout/user/img/gnb_btn.svg');
            $icon.attr('alt', '메뉴 열기');
        } else {
            $overlay.fadeIn(250);
            $menu.slideDown(250);
            $icon.attr('src', 'https://wfps.or.kr/layout/user/img/gnb_close.svg');
            $icon.attr('alt', '메뉴 닫기');
        }
    });
});

